def clean(df):
    df = df.copy()
    # remove exact duplicate rows
    df = df.drop_duplicates().reset_index(drop=True)
    # normalize category label variants
    cat_map = {
        'accessories': 'Accessories',
        'furnture': 'Furniture',
        'office supplies': 'Office Supplies',
    }
    df['Category'] = df['Category'].astype(str).str.strip().str.lower().map(
        lambda x: cat_map.get(x, x.strip().title())
    )
    # fix known title-case variants explicitly
    df['Category'] = df['Category'].replace({'Furnture': 'Furniture'})
    return df

def answer(df):
    d = clean(df)
    counts = d.dropna(subset=['Category']).groupby('Category').size()
    return {str(k): int(v) for k, v in counts.items()}
